<template>
  <LargeAlert
    variant="default"
    :title="title"
    :description="description"
    :icon="icon || SearchXIcon"
    :icon-class="iconClass"
    :card="variants[variant].card"
    :class="cn('mx-auto p-0 px-0 sm:px-8 flex items-center justify-center', variants[variant].class)"
  >
    <slot />
  </LargeAlert>
</template>

<script lang="ts" setup>
import { cn } from '@/lib/utils';
import { SearchXIcon } from 'lucide-vue-next';
import type { FunctionalComponent } from 'vue';

interface Props {
  title?: string;
  description?: string;
  variant?: 'page' | 'table';
  iconClass?: string;
  subject?: string;
  icon?: FunctionalComponent;
}

const props = withDefaults(defineProps<Props>(), {
  title: undefined,
  description: undefined,
  variant: 'page',
  subject: undefined,
  iconClass: 'text-muted-foreground',
  icon: undefined,
});

const variants = {
  table: {
    card: false,
    class: 'min-h-48 py-4',
  },
  page: {
    card: true,
    class: 'min-h-80',
  },
};

const description = computed(() => {
  if (props.description) return props.description;
  if (props.subject) return `No ${props.subject} found`;
  return 'No items found';
});
</script>

<style lang="scss" scoped></style>
